// Basic vertex shader with all coordinate transformations
struct Attributes
{
    float4 positionOS : POSITION;      // Object space position
    float2 uv         : TEXCOORD0;     // Texture coordinates
    float3 normalOS   : NORMAL;        // Object space normal
};

struct Varyings
{
    float4 positionHCS : SV_POSITION;  // Clip space position (REQUIRED)
    float2 uv          : TEXCOORD0;    // Pass UV to fragment shader
    float3 normalWS    : TEXCOORD1;    // Pass world normal
};

Varyings vert(Attributes input)
{
    Varyings output;

    // Transform object-space position to clip-space (screen-ready)
    output.positionHCS = TransformObjectToHClip(input.positionOS);

    // Pass UV coordinates through unchanged
    output.uv = input.uv;

    // Transform normal to world space for lighting calculations
    output.normalWS = TransformObjectToWorldNormal(input.normalOS);

    return output;
}

// Common transformation functions in URP

// Object Space → World Space
float3 worldPos = TransformObjectToWorld(input.positionOS.xyz);

// Object Space → Clip Space (most common — goes straight to screen)
float4 clipPos = TransformObjectToHClip(input.positionOS);

// World Space → View Space (camera-relative)
float3 viewPos = TransformWorldToView(worldPos);

// World Space → Clip Space
float4 clipFromWorld = TransformWorldToHClip(worldPos);

// Normal transformations
float3 worldNormal = TransformObjectToWorldNormal(input.normalOS);
float3 viewNormal = TransformWorldToViewDir(worldNormal);

// Vertex displacement: make a plane wave like water
float _WaveSpeed;
float _WaveHeight;

Varyings vert(Attributes input)
{
    Varyings output;

    // Copy the original position
    float3 positionOS = input.positionOS.xyz;

    // Displace Y based on X position and time
    float wave = sin(positionOS.x * 2.0 + _Time.y * _WaveSpeed);
    positionOS.y += wave * _WaveHeight;

    // Transform the displaced position to clip space
    output.positionHCS = TransformObjectToHClip(float4(positionOS, 1.0));
    output.uv = input.uv;

    return output;
}

