// Cel-shading with 3 light bands
float _ShadowThreshold;
float _MidThreshold;
half4 _ShadowColor;
half4 _MidColor;
half4 _HighlightColor;

half4 frag(Varyings input) : SV_Target
{
    half3 normalWS = normalize(input.normalWS);
    Light mainLight = GetMainLight();
    half NdotL = saturate(dot(normalWS, mainLight.direction));

    // Quantize into 3 bands using thresholds
    half lightBand;
    if (NdotL < _ShadowThreshold)
        lightBand = 0; // Shadow
    else if (NdotL < _MidThreshold)
        lightBand = 1; // Mid-tone
    else
        lightBand = 2; // Highlight

    // Smooth transitions between bands (optional but nicer)
    half shadowBlend = smoothstep(_ShadowThreshold - 0.05, _ShadowThreshold, NdotL);
    half midBlend = smoothstep(_MidThreshold - 0.05, _MidThreshold, NdotL);

    // Pick color based on band
    half3 color = lerp(_ShadowColor.rgb, _MidColor.rgb, shadowBlend);
    color = lerp(color, _HighlightColor.rgb, midBlend);

    return half4(color, 1);
}

// Rim lighting calculation
float _RimPower;
half4 _RimColor;

half4 frag(Varyings input) : SV_Target
{
    half3 normalWS = normalize(input.normalWS);
    half3 viewDirectionWS = GetWorldSpaceNormalizeViewDir(input.positionWS);

    // Rim is strongest when normal faces away from camera
    half NdotV = saturate(dot(normalWS, viewDirectionWS));
    half rim = 1.0 - NdotV;

    // Sharpen or soften the rim falloff
    rim = pow(rim, _RimPower);

    // Combine with base color
    half3 baseColor = _BaseColor.rgb;
    half3 finalColor = baseColor + (_RimColor.rgb * rim);

    return half4(finalColor, 1);
}

