// Reusable custom lighting function
half3 CustomLighting(half3 normalWS, half3 lightDir, half3 lightColor, half3 baseColor)
{
    half NdotL = saturate(dot(normalWS, lightDir));

    // Custom step function: 3 hard bands
    half3 litColor;
    if (NdotL > 0.7)
        litColor = baseColor * lightColor * 1.0;  // Full bright
    else if (NdotL > 0.3)
        litColor = baseColor * lightColor * 0.6;  // Mid tone
    else
        litColor = baseColor * lightColor * 0.2;  // Shadow

    return litColor;
}

