    // Add rim on top
    half3 viewDir = GetWorldSpaceNormalizeViewDir(input.positionWS);
    half rim = pow(1 - saturate(dot(normalWS, viewDir)), _RimPower);
    color += _RimColor.rgb * rim;

    return half4(color, 1);
