Shader "Custom/TextureBlend"
{
    Properties
    {
        _BaseTex("Base Texture", 2D) = "white" {}
        _OverlayTex("Overlay Texture", 2D) = "white" {}
        _BlendMask("Blend Mask", 2D) = "white" {}
        _BlendStrength("Blend Strength", Range(0, 1)) = 1
    }
    SubShader
    {
        Pass
        {
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D(_BaseTex); SAMPLER(sampler_BaseTex);
            TEXTURE2D(_OverlayTex); SAMPLER(sampler_OverlayTex);
            TEXTURE2D(_BlendMask); SAMPLER(sampler_BlendMask);
            float _BlendStrength;

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            Varyings vert(Attributes input)
            {
                Varyings output;
                output.positionHCS = TransformObjectToHClip(input.positionOS);
                output.uv = input.uv;
                return output;
            }

            half4 frag(Varyings input) : SV_Target
            {
                half4 base = SAMPLE_TEXTURE2D(_BaseTex, sampler_BaseTex, input.uv);
                half4 overlay = SAMPLE_TEXTURE2D(_OverlayTex, sampler_OverlayTex, input.uv);
                half mask = SAMPLE_TEXTURE2D(_BlendMask, sampler_BlendMask, input.uv).r;

                // Blend based on mask, modulated by strength
                mask = saturate(mask * _BlendStrength);
                half4 finalColor = lerp(base, overlay, mask);

                return finalColor;
            }
            ENDHLSL
        }
    }
}

// Triplanar texture mapping
float _TriplanarScale;

half4 TriplanarSample(TEXTURE2D_PARAM(tex, sampler_tex), float3 positionWS, float3 normalWS)
{
    // Sample from three axes using world position
    half4 xProj = SAMPLE_TEXTURE2D(tex, sampler_tex, positionWS.yz * _TriplanarScale);
    half4 yProj = SAMPLE_TEXTURE2D(tex, sampler_tex, positionWS.xz * _TriplanarScale);
    half4 zProj = SAMPLE_TEXTURE2D(tex, sampler_tex, positionWS.xy * _TriplanarScale);

    // Blend weights based on normal direction (absolute value)
    float3 blendWeights = abs(normalWS);
    blendWeights = pow(blendWeights, 3); // Sharpen the blend
    blendWeights /= (blendWeights.x + blendWeights.y + blendWeights.z);

    // Weighted combination
    return xProj * blendWeights.x + yProj * blendWeights.y + zProj * blendWeights.z;
}

