// Sprite sheet animation in shader
float _Columns;      // Number of columns in atlas
float _Rows;         // Number of rows in atlas
float _FrameIndex;   // Current animation frame

half4 frag(Varyings input) : SV_Target
{
    // Calculate frame position in grid
    float frameX = fmod(_FrameIndex, _Columns);
    float frameY = floor(_FrameIndex / _Columns);

    // Calculate UV offset and scale for this frame
    float2 cellSize = float2(1.0 / _Columns, 1.0 / _Rows);
    float2 cellOffset = float2(frameX * cellSize.x, (_Rows - 1 - frameY) * cellSize.y);

    // Remap UVs to the current frame
    float2 atlasUV = input.uv * cellSize + cellOffset;

    return SAMPLE_TEXTURE2D(_SpriteSheet, sampler_SpriteSheet, atlasUV);
}

