half4 frag(Varyings input) : SV_Target
{
    // Get screen-space UVs (0-1 range)
    float2 screenUV = input.positionHCS.xy / _ScaledScreenParams.xy;

    // Sample scene depth (non-linear, raw depth buffer value)
    float sceneDepth = SampleSceneDepth(screenUV);

    // Convert to linear eye depth (actual distance from camera in world units)
    float sceneLinearDepth = LinearEyeDepth(sceneDepth, _ZBufferParams);

    // Get our object's linear depth
    float objectLinearDepth = LinearEyeDepth(input.positionHCS.z, _ZBufferParams);

    // Difference = how much the scene is behind our object
    float depthDifference = sceneLinearDepth - objectLinearDepth;

    return half4(depthDifference.xxx * 0.1, 1); // Visualize as grayscale
}

