// Soft particle depth fade
float _SoftParticleFade;

half4 frag(Varyings input) : SV_Target
{
    half4 particleColor = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);

    // Sample scene depth at this pixel
    float2 screenUV = input.positionHCS.xy / _ScaledScreenParams.xy;
    float sceneDepth = LinearEyeDepth(SampleSceneDepth(screenUV), _ZBufferParams);
    float particleDepth = LinearEyeDepth(input.positionHCS.z, _ZBufferParams);

    // Fade factor: 1 when far from geometry, 0 when close/intersecting
    float depthDelta = sceneDepth - particleDepth;
    float fade = saturate(depthDelta * _SoftParticleFade);

    particleColor.a *= fade;
    return particleColor;
}

// _SoftParticleFade = 1.0 → gentle fade
// _SoftParticleFade = 10.0 → sharp fade near surfaces

