// Key differences summary:

// Vertex/Fragment Shader:
// - Fixed pipeline: vertex → rasterize → fragment
// - Outputs: SV_POSITION, SV_Target
// - Best for: rendering meshes, standard materials
// - Limited to: one output per pixel

// Compute Shader:
// - Free-form: any thread can write anywhere
// - Outputs: RWTexture, RWStructuredBuffer, RWBuffer
// - Best for: simulation, procedural generation, post-processing
// - Can: read/write shared memory, use thread synchronization

// Shared memory for fast inter-thread communication
groupshared float sharedData[256];

[numthreads(256, 1, 1)]
void ReduceSum(uint3 id : SV_GroupThreadID)
{
    sharedData[id.x] = inputData[id.x];
    GroupMemoryBarrierWithGroupSync();

    for (uint stride = 128; stride > 0; stride /= 2)
    {
        if (id.x < stride)
            sharedData[id.x] += sharedData[id.x + stride];
        GroupMemoryBarrierWithGroupSync();
    }

    if (id.x == 0)
        outputData[0] = sharedData[0];
}

