            #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/Color.hlsl"

            float _Intensity, _Smoothness;
            half4 _Color;

            float4 vert(uint vertexID : SV_VertexID) : SV_POSITION
            {
                float2 uv = float2(vertexID % 2, vertexID / 2) * 2;
                return float4(uv * 2 - 1, 0, 1);
            }

            half4 frag(float4 positionHCS : SV_POSITION) : SV_Target
            {
                float2 screenUV = positionHCS.xy / _ScaledScreenParams.xy;
                half3 sceneColor = SampleSceneColor(screenUV);

                float2 center = screenUV - 0.5;
                float dist = length(center);
                float vignette = 1 - smoothstep(0.3, 0.3 + _Smoothness, dist);
                vignette = lerp(1, vignette, _Intensity);

                half3 finalColor = lerp(_Color.rgb, sceneColor, vignette);
                return half4(finalColor, 1);
            }
            ENDHLSL
        }
    }
}

// Chromatic aberration post-processing
float _ChromaticIntensity;

half4 frag(float4 positionHCS : SV_POSITION) : SV_Target
{
    float2 screenUV = positionHCS.xy / _ScaledScreenParams.xy;
    float2 centerOffset = screenUV - 0.5;
    float dist = length(centerOffset);

    float2 direction = normalize(centerOffset);
    float2 aberration = direction * dist * dist * _ChromaticIntensity;

    float r = SampleSceneColor(screenUV + aberration * 1.0).r;
    float g = SampleSceneColor(screenUV + aberration * 0.5).g;
    float b = SampleSceneColor(screenUV - aberration * 0.5).b;

    return half4(r, g, b, 1);
}

