using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class CustomPostProcessFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public Material postProcessMaterial;
        public RenderPassEvent renderPassEvent = RenderPassEvent.AfterRenderingPostProcessing;
    }

    public Settings settings = new Settings();
    private CustomPostProcessPass pass;

    public override void Create()
    {
        pass = new CustomPostProcessPass(settings);
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData data)
    {
        renderer.EnqueuePass(pass);
    }
}

public class CustomPostProcessPass : ScriptableRenderPass
{
    private Material material;
    private RenderTargetHandle tempTexture;

    public CustomPostProcessPass(Settings settings)
    {
        this.material = settings.postProcessMaterial;
        this.renderPassEvent = settings.renderPassEvent;
        tempTexture.Init("_TempTexture");
    }

    public override void Execute(ScriptableRenderContext context, ref RenderingData data)
    {
        CommandBuffer cmd = CommandBufferPool.Get("CustomPostProcess");
        RenderTargetIdentifier cameraColorTarget = data.cameraData.renderer.cameraColorTarget;
        RenderTextureDescriptor descriptor = data.cameraData.cameraTargetDescriptor;
        cmd.GetTemporaryRT(tempTexture.id, descriptor);
        Blit(cmd, cameraColorTarget, tempTexture.Identifier(), material);
        Blit(cmd, tempTexture.Identifier(), cameraColorTarget);
        context.ExecuteCommandBuffer(cmd);
        CommandBufferPool.Release(cmd);
    }
}

