Shader "Custom/StylizedWater"
{
    Properties
    {
        [Header(Wave Settings)]
        _WaveSpeed("Wave Speed", Float) = 1
        _WaveHeight("Wave Height", Range(0, 1)) = 0.2
        _WaveFrequency("Wave Frequency", Float) = 2

        [Header(Surface)]
        _BaseColor("Deep Color", Color) = (0, 0.3, 0.5, 0.8)
        _ShallowColor("Shallow Color", Color) = (0, 0.8, 1, 0.6)
        _NormalMap("Normal Map", 2D) = "bump" {}
        _NormalStrength("Normal Strength", Range(0, 2)) = 1
        _NormalSpeed("Normal Scroll Speed", Float) = 0.5

