        _FoamColor("Foam Color", Color) = (1, 1, 1, 1)
        _FoamWidth("Foam Width", Range(0.01, 2)) = 0.5
        _FoamIntensity("Foam Intensity", Range(0, 5)) = 2

        [Header(Specular)]
        _SpecularColor("Specular Color", Color) = (1, 1, 0.9, 1)
        _Shininess("Shininess", Range(1, 256)) = 64
    }
    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" }
        Pass
        {
            Blend SrcAlpha OneMinusSrcAlpha
            ZWrite Off

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"

            float _WaveSpeed, _WaveHeight, _WaveFrequency;
            half4 _BaseColor, _ShallowColor, _FoamColor, _SpecularColor;
            float _NormalStrength, _NormalSpeed, _FoamWidth, _FoamIntensity, _Shininess;
            TEXTURE2D(_NormalMap); SAMPLER(sampler_NormalMap);

            struct Attributes
            {
                float4 positionOS : POSITION;
                float3 normalOS   : NORMAL;
                float4 tangentOS  : TANGENT;
                float2 uv         : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float3 positionWS  : TEXCOORD0;
                float2 uv          : TEXCOORD1;
                float4 screenPos   : TEXCOORD2;
                float3 normalWS    : TEXCOORD3;
                float3 tangentWS   : TEXCOORD4;
                float3 bitangentWS : TEXCOORD5;
            };

            Varyings vert(Attributes input)
            {
                Varyings output;

                float3 posOS = input.positionOS.xyz;
                float wave1 = sin(posOS.x * _WaveFrequency + _Time.y * _WaveSpeed);
                float wave2 = cos(posOS.z * _WaveFrequency * 0.5 + _Time.y * _WaveSpeed * 0.8);
                posOS.y += (wave1 + wave2) * _WaveHeight * 0.5;

                output.positionHCS = TransformObjectToHClip(float4(posOS, 1));
                output.positionWS = TransformObjectToWorld(float4(posOS, 1)).xyz;
                output.uv = input.uv;
                output.screenPos = ComputeScreenPos(output.positionHCS);

                VertexNormalInputs normalInputs = GetVertexNormalInputs(input.normalOS, input.tangentOS);
                output.normalWS = normalInputs.normalWS;
                output.tangentWS = normalInputs.tangentWS;
                output.bitangentWS = normalInputs.bitangentWS;

                return output;
            }

            half4 frag(Varyings input) : SV_Target
            {
                float2 scrollUV = input.uv + float2(_Time.y * _NormalSpeed, 0);
                half3 normalTS = UnpackNormal(SAMPLE_TEXTURE2D(_NormalMap, sampler_NormalMap, scrollUV));
                normalTS.xy *= _NormalStrength;
                normalTS.z = sqrt(1 - saturate(dot(normalTS.xy, normalTS.xy)));

                half3 normalWS = normalize(
                    normalTS.x * input.tangentWS +
                    normalTS.y * input.bitangentWS +
                    normalTS.z * input.normalWS
                );

                float2 screenUV = input.screenPos.xy / input.screenPos.w;
                float sceneDepth = LinearEyeDepth(SampleSceneDepth(screenUV), _ZBufferParams);
                float waterDepth = LinearEyeDepth(input.positionHCS.z, _ZBufferParams);
                float depthDiff = sceneDepth - waterDepth;
                float foam = 1 - saturate(depthDiff / _FoamWidth);
                foam = pow(foam, _FoamIntensity);

                float depthFactor = saturate(depthDiff / 5.0);
                half3 waterColor = lerp(_ShallowColor.rgb, _BaseColor.rgb, depthFactor);

                Light mainLight = GetMainLight();
                float3 viewDirWS = GetWorldSpaceNormalizeViewDir(input.positionWS);
                float3 halfVector = normalize(mainLight.direction + viewDirWS);
                half NdotH = saturate(dot(normalWS, halfVector));
                half specular = pow(NdotH, _Shininess);

                half3 finalColor = waterColor + (specular * _SpecularColor.rgb * mainLight.color);
                finalColor = lerp(finalColor, _FoamColor.rgb, foam);

                half alpha = lerp(_ShallowColor.a, _BaseColor.a, depthFactor);

                return half4(finalColor, alpha);
            }
            ENDHLSL
        }
    }
}

